<template>
  <section><div class="catalog-heading"><div><p class="eyebrow">AI 问答管理</p><h1>敏感词与拦截规则</h1><p class="muted">输入规则在外部调用前检查；输出文字在流式发送前检查，支持跨片段匹配。</p></div><button type="button" class="primary-button" @click="reset">＋ 新建规则</button></div><PageStatus :loading="loading" :error="error" :empty="!rules.length" empty-text="暂无规则。可以按文字或输入关键词组合维护。" @retry="load" /><div v-if="rules.length" class="table-scroll"><table class="admin-table"><thead><tr><th>规则</th><th>阶段 / 匹配</th><th>优先级</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="rule in rules" :key="rule.id"><td><strong>{{ rule.name }}</strong><small>{{ rule.terms.join('、') }}</small></td><td>{{ rule.scope === 'INPUT' ? '输入' : '输出' }} · {{ rule.matchMode }}<small>版本 {{ rule.version }}</small></td><td>{{ rule.priority }}</td><td>{{ rule.enabled ? '已启用' : '已停用' }}</td><td><div class="table-actions"><button type="button" class="text-action" @click="edit(rule)">编辑</button><button type="button" class="text-action" :disabled="busy" @click="toggle(rule)">{{ rule.enabled ? '停用' : '启用' }}</button></div></td></tr></tbody></table><PagePagination :page="page" :size="20" :total="total" @change="value => { page = value; load() }" /></div>
    <section v-if="editing" class="editor-section"><div class="catalog-heading"><h2>{{ current ? '编辑规则' : '新建规则' }}</h2><button type="button" class="text-action" @click="editing = false">收起</button></div><p v-if="editorError" class="form-message-error" role="alert">{{ editorError }}</p><form @submit.prevent="save"><div class="address-fields"><label class="form-field">规则名称<input v-model.trim="form.name" required maxlength="100"></label><label class="form-field">检查阶段<select v-model="form.scope"><option value="INPUT">用户输入</option><option value="OUTPUT">回答输出</option></select></label><label class="form-field">匹配方式<select v-model="form.matchMode" :disabled="form.scope === 'OUTPUT'"><option value="LITERAL">文字包含（任一命中）</option><option v-if="form.scope === 'INPUT'" value="ALL">关键词全部包含</option><option v-if="form.scope === 'INPUT'" value="ANY">关键词任一包含</option></select></label><label class="form-field">优先级（越高越优先）<input v-model.number="form.priority" type="number" required min="0" max="999" step="1"></label><label class="form-field address-field-wide">匹配文字（每行一条，最多20条，每条100字）<textarea v-model="terms" rows="5" required></textarea><small class="field-hint">文字按字面匹配，不执行正则或表达式，也不代表覆盖所有语义攻击。</small></label><label class="form-field address-field-wide">拦截提示<input v-model="form.message" required maxlength="200" placeholder="例如：这个问题暂时无法提供回答，请调整表达。"></label><label class="checkbox-field"><input v-model="form.enabled" type="checkbox">启用规则</label></div><button class="primary-button" :disabled="busy">{{ busy ? '保存中…' : '保存规则' }}</button></form></section>
    <section class="editor-section"><h2>匹配试验</h2><form class="rule-test" @submit.prevent="test"><select v-model="scope" aria-label="测试阶段"><option value="INPUT">输入文字</option><option value="OUTPUT">输出文字</option></select><input v-model="question" required maxlength="1000" placeholder="输入测试文字" aria-label="规则测试文字"><button class="secondary-button" :disabled="testing">{{ testing ? '测试中…' : '测试已启用规则' }}</button></form><p v-if="testError" class="form-message-error">{{ testError }}</p><div v-if="result" class="rule-result"><strong>{{ result.blocked ? '文字会被拦截' : '没有命中已启用规则' }}</strong><p v-for="rule in result.rules" :key="rule.id">{{ rule.name }} · 版本 {{ rule.version }} · {{ rule.message }}</p><p class="field-hint">实际问答在接受时固定规则快照，保存后的规则用于新请求。</p></div></section>
  </section>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import PageStatus from '../components/PageStatus.vue'
import PagePagination from '../components/PagePagination.vue'
import { errorMessage } from '../api/catalog'
import * as api from '../api/admin-ai'
const fresh = (): api.RuleInput => ({ name: '', scope: 'INPUT', matchMode: 'LITERAL', terms: [], priority: 0, message: '这个问题暂时无法提供回答，请调整表达。', enabled: true })
const form = reactive(fresh()), terms = ref(''), rules = ref<api.Rule[]>([]), current = ref<api.Rule | null>(null), editing = ref(false), loading = ref(false), error = ref(''), editorError = ref(''), busy = ref(false)
const page = ref(1), total = ref(0)
const question = ref(''), scope = ref('INPUT'), testing = ref(false), testError = ref(''), result = ref<Awaited<ReturnType<typeof api.testRules>> | null>(null)
function reset() { current.value = null; Object.assign(form, fresh(), { version: undefined }); terms.value = ''; editing.value = true; editorError.value = '' }
function edit(rule: api.Rule) { current.value = rule; Object.assign(form, rule); terms.value = rule.terms.join('\n'); editing.value = true; editorError.value = '' }
async function load() { loading.value = true; error.value = ''; try { const result = await api.listRules(page.value); rules.value = result.items; total.value = result.total } catch (failure) { rules.value = []; editing.value = false; current.value = null; error.value = errorMessage(failure) } finally { loading.value = false } }
async function save() { busy.value = true; editorError.value = ''; try { edit(await api.saveRule(current.value?.id ?? null, { ...form, terms: terms.value.split('\n').map(s => s.trim()).filter(Boolean) })); await load() } catch (failure) { editorError.value = errorMessage(failure) } finally { busy.value = false } }
async function toggle(rule: api.Rule) { busy.value = true; try { const updated = await api.enableRule(rule); if (current.value?.id === rule.id) edit(updated); await load() } catch (failure) { error.value = errorMessage(failure) } finally { busy.value = false } }
async function test() { testing.value = true; testError.value = ''; try { result.value = await api.testRules(question.value, scope.value) } catch (failure) { testError.value = errorMessage(failure) } finally { testing.value = false } }
watch(() => form.scope, value => { if (value === 'OUTPUT') form.matchMode = 'LITERAL' })
onMounted(load)
</script>
<style scoped>
.admin-table td{max-width:350px;overflow-wrap:anywhere}.admin-table small{display:block;font-size:11px;color:#8a9681;margin-top:6px}.rule-test{display:flex;flex-wrap:wrap;gap:12px;margin:18px 0}.rule-test input,.rule-test select{border:1px solid #d6e1d0;border-radius:6px;padding:9px 11px;font:inherit;font-size:13px}.rule-test input{flex:1;min-width:180px}.rule-result{padding:15px 18px;border-left:3px solid #90b883;background:#f6f9f1;font-size:12px;color:#5c7750;line-height:1.8}
</style>
